package com.suarez.clinica; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*; import java.util.concurrent.atomic.AtomicLong; @RestController @RequestMapping("/api") public class ClinicaController { public enum Estado{PROGRAMADA,CONFIRMADA,ATENDIDA,CANCELADA} public record Paciente(Long id,@NotBlank @Pattern(regexp="\\d{8}") String dni,@NotBlank String nombres,@NotBlank String apellidos,String telefono,String correo){} public record Medico(Long id,@NotBlank String cmp,@NotBlank String nombres,@NotBlank String apellidos,@NotNull Long especialidadId){} public record Cita(Long id,@NotNull LocalDate fecha,@NotNull LocalTime hora,@NotNull Long pacienteId,@NotNull Long medicoId,String motivo,Estado estado){} private final Map<Long,Paciente> pacientes=new LinkedHashMap<>();private final Map<Long,Medico> medicos=new LinkedHashMap<>();private final Map<Long,Cita> citas=new LinkedHashMap<>();private final AtomicLong p=new AtomicLong(),m=new AtomicLong(),c=new AtomicLong(); @PostMapping("/pacientes") @ResponseStatus(HttpStatus.CREATED) public Paciente paciente(@Valid @RequestBody Paciente x){var z=new Paciente(p.incrementAndGet(),x.dni(),x.nombres(),x.apellidos(),x.telefono(),x.correo());pacientes.put(z.id(),z);return z;} @GetMapping("/pacientes") public Collection<Paciente> pacientes(){return List.copyOf(pacientes.values());} @GetMapping("/pacientes/{id}") public Paciente paciente(@PathVariable long id){return req(pacientes,id);} @PutMapping("/pacientes/{id}") public Paciente updPaciente(@PathVariable long id,@Valid @RequestBody Paciente x){req(pacientes,id);var z=new Paciente(id,x.dni(),x.nombres(),x.apellidos(),x.telefono(),x.correo());pacientes.put(id,z);return z;} @DeleteMapping("/pacientes/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delPaciente(@PathVariable long id){del(pacientes,id);} @PostMapping("/medicos") @ResponseStatus(HttpStatus.CREATED) public Medico medico(@Valid @RequestBody Medico x){var z=new Medico(m.incrementAndGet(),x.cmp(),x.nombres(),x.apellidos(),x.especialidadId());medicos.put(z.id(),z);return z;} @GetMapping("/medicos") public Collection<Medico> medicos(){return List.copyOf(medicos.values());} @GetMapping("/medicos/{id}") public Medico medico(@PathVariable long id){return req(medicos,id);} @PutMapping("/medicos/{id}") public Medico updMedico(@PathVariable long id,@Valid @RequestBody Medico x){req(medicos,id);var z=new Medico(id,x.cmp(),x.nombres(),x.apellidos(),x.especialidadId());medicos.put(id,z);return z;} @DeleteMapping("/medicos/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delMedico(@PathVariable long id){del(medicos,id);} @PostMapping("/citas") @ResponseStatus(HttpStatus.CREATED) public Cita cita(@Valid @RequestBody Cita x){req(pacientes,x.pacienteId());req(medicos,x.medicoId());var z=new Cita(c.incrementAndGet(),x.fecha(),x.hora(),x.pacienteId(),x.medicoId(),x.motivo(),Estado.PROGRAMADA);citas.put(z.id(),z);return z;} @GetMapping("/citas") public Collection<Cita> citas(){return List.copyOf(citas.values());} @GetMapping("/citas/{id}") public Cita cita(@PathVariable long id){return req(citas,id);} @PatchMapping("/citas/{id}/estado") public Cita estado(@PathVariable long id,@RequestParam Estado valor){var x=req(citas,id);var z=new Cita(x.id(),x.fecha(),x.hora(),x.pacienteId(),x.medicoId(),x.motivo(),valor);citas.put(id,z);return z;} @DeleteMapping("/citas/{id}") public Cita cancelar(@PathVariable long id){return estado(id,Estado.CANCELADA);} private <T>T req(Map<Long,T> x,long id){T v=x.get(id);if(v==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return v;} private <T>void del(Map<Long,T>x,long id){if(x.remove(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);} }
